using PerformanceMonitor.PlanAnalysis;
using Xunit;

namespace Darling.Tests;

/// <summary>
/// #4521 — Rule 15 (Join OR Clause) matched the Nested Loops / Merge Interval / Top N Sort /
/// Concatenation / two-or-more-Constant-Scan operator shape alone. <c>WHERE t.A IN (@p1, @p2)</c>
/// on an indexed column builds the identical dynamic-seek shape (each Constant Scan branch produces
/// only a parameter), so a query with no join at all was told to rewrite as a UNION ALL. The rule
/// now also reads what each lookup branch produces (<see cref="PlanNode.DefinedValues"/> /
/// <see cref="PlanNode.ConstantScanValues"/>) and fires only when a branch takes its value from
/// another input — an outer column, or an expression the outer input computed
/// (<c>[Expr1002]</c> for <c>ON t.A = o.X + 1 OR ...</c>). Branches of parameters, variables,
/// literals and functions of them are a parameter list.
///
/// <para>The dynamic-seek fixture is a real SQL Server 2022 actual plan for
/// <c>(@p1 int, @p2 int)SELECT t.Id, t.A FROM dbo.T AS t WHERE t.A IN (@p1, @p2)</c> against
/// <c>dbo.T(Id, A)</c> with a nonclustered index on <c>A</c>. The mixed fixture is the same plan
/// with one Constant Scan branch's parameter reference (<c>[@p1]</c>) replaced by an outer-column
/// reference (<c>[Repro].[dbo].[O].[X] as [o].[X]</c>), standing in for a real join OR whose other
/// branch still carries a parameter.</para>
/// </summary>
public sealed class PlanSync4521Tests
{
