    private static ParsedPlan ParseAndAnalyze(string xml)
    {
        var plan = ShowPlanParser.Parse(xml);
        PlanAnalyzer.Analyze(plan);
        return plan;
    }

    /// <summary>
    /// (a) WHERE t.A IN (@p1, @p2): a dynamic seek whose Constant Scan branches carry only
    /// [@p1]/[@p2]. Before the fix this fired the Join OR Clause warning on a query with no join.
    /// </summary>
    [Fact]
    public void Rule15_DynamicSeekForParameterInList_NotFlagged()
    {
        var plan = ParseAndAnalyze(DynamicSeekXml);

        Assert.DoesNotContain(plan.AllWarnings, w => w.WarningType == "Join OR Clause");
    }

    /// <summary>
    /// (b) One Constant Scan branch carries an outer column ([o].[X]); the other still carries a
    /// parameter ([@p2]). One branch that reads another input is enough to keep the warning — the
    /// shape guard must not cost a real join OR just because it is mixed with a parameter branch.
    /// </summary>
    [Fact]
    public void Rule15_ColumnBranchNextToParameterBranch_IsFlagged()
    {
        var plan = ParseAndAnalyze(MixedColumnParameterXml);

        Assert.Contains(plan.AllWarnings, w => w.WarningType == "Join OR Clause");
    }

    /// <summary>
    /// The branch values the parser records for the reporter's own plan: two parameters and a
    /// literal. The same holds for local variables ([@a]), which read like parameters, and for a
    /// function of a parameter ([dbo].[fn]([@p1])).
    /// </summary>
    [Theory]
    [InlineData("Expr1002 = [@p2]; Expr1003 = [@p2]; Expr1001 = (62)")]
    [InlineData("Expr1004 = [@a]; Expr1005 = [@a]")]
    [InlineData("Expr1002 = [dbo].[fn]([@p1])")]
    public void Rule15_ParameterOrVariableOnlyLookup_DoesNotReadAnotherInput(string values)
    {
        Assert.False(PlanAnalyzer.ReadsAnotherInput(values));
    }

    /// <summary>
    /// (c) A variable ([@v]) counts as a parameter list, not a read of another input.
    /// </summary>
    [Fact]
    public void Rule15_VariableBranch_CountsLikeParameter()
    {
        Assert.False(PlanAnalyzer.ReadsAnotherInput("Expr1002 = [@v]; Expr1001 = (62)"));
    }

    /// <summary>
    /// A column, or an expression the outer input computed ([Expr1002] for ON t.A = o.X + 1 OR
    /// ...), reads another input and keeps the warning.
    /// </summary>
    [Theory]
    [InlineData("Expr1005 = [Repro].[dbo].[O].[X] as [o].[X]; Expr1004 = (62)")]
    [InlineData("Expr1010 = [Expr1002]; Expr1011 = [Expr1002]; Expr1009 = (62)")]
    public void Rule15_LookupFromAnotherInput_IsRecognized(string values)
    {
        Assert.True(PlanAnalyzer.ReadsAnotherInput(values));
    }

    /// <summary>
    /// A bracket inside a string literal is text, not a name. Read as a name, it would turn an IN
    /// list of strings back into a false join OR.
    /// </summary>
    [Fact]
    public void Rule15_BracketInsideStringLiteral_IsNotAName()
    {
        Assert.False(PlanAnalyzer.ReadsAnotherInput("Expr1002 = N'[Posts].[OwnerUserId]'; Expr1001 = (62)"));
    }
}
